"""Configuration loading for the Galbot MCP server."""

from __future__ import annotations

import json
import os
from pathlib import Path
from typing import Any, Literal

from pydantic import BaseModel, ConfigDict, Field, field_validator


ENV_PREFIX = "GALBOT_MCP_"


class PartialServiceConfig(BaseModel):
    """Optional config values loaded from JSON files or the environment."""

    model_config = ConfigDict(extra="forbid")

    transport: Literal["streamable-http", "stdio"] | None = None
    host: str | None = None
    port: int | None = None
    mount_path: str | None = None
    auth_token: str | None = None
    sdk_root: Path | None = None
    interface_config_path: Path | None = None
    robot_cfg: str | None = None
    log_level: Literal["DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL"] | None = None

    @field_validator("sdk_root", "interface_config_path")
    @classmethod
    def _expand_path(cls, value: Path | None) -> Path | None:
        return value.expanduser().resolve() if value is not None else None

    @field_validator("mount_path")
    @classmethod
    def _normalize_partial_mount_path(cls, value: str | None) -> str | None:
        if value is None:
            return None
        if not value.startswith("/"):
            value = "/" + value
        return value.rstrip("/") or "/galbot_mcp"


class ServiceConfig(BaseModel):
    """Runtime config with defaults applied."""

    model_config = ConfigDict(extra="forbid")

    transport: Literal["streamable-http", "stdio"] = "streamable-http"
    host: str = "0.0.0.0"
    port: int = 8000
    mount_path: str = "/galbot_mcp"
    auth_token: str | None = None
    sdk_root: Path | None = None
    interface_config_path: Path = Field(
        default_factory=lambda: Path(__file__).resolve().parents[2]
        / "robot_interface"
        / "eval_config.yml"
    )
    robot_cfg: str = "robot_config.yaml"
    log_level: Literal["DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL"] = "INFO"

    @field_validator("sdk_root", "interface_config_path")
    @classmethod
    def _expand_path(cls, value: Path | None) -> Path | None:
        return value.expanduser().resolve() if value is not None else None

    @field_validator("mount_path")
    @classmethod
    def _normalize_mount_path(cls, value: str) -> str:
        if not value.startswith("/"):
            value = "/" + value
        return value.rstrip("/") or "/galbot_mcp"


def _load_json_config(config_path: Path | None) -> dict[str, Any]:
    if config_path is None:
        return {}
    with config_path.expanduser().resolve().open("r", encoding="utf-8") as fh:
        return json.load(fh)


def _load_env_config(env: dict[str, str] | None = None) -> dict[str, str]:
    source = env or os.environ
    mapping = {
        "transport": source.get(f"{ENV_PREFIX}TRANSPORT"),
        "host": source.get(f"{ENV_PREFIX}HOST"),
        "port": source.get(f"{ENV_PREFIX}PORT"),
        "mount_path": source.get(f"{ENV_PREFIX}MOUNT_PATH"),
        "auth_token": source.get(f"{ENV_PREFIX}AUTH_TOKEN"),
        "sdk_root": source.get(f"{ENV_PREFIX}SDK_ROOT"),
        "interface_config_path": source.get(f"{ENV_PREFIX}INTERFACE_CONFIG_PATH"),
        "robot_cfg": source.get(f"{ENV_PREFIX}ROBOT_CFG"),
        "log_level": source.get(f"{ENV_PREFIX}LOG_LEVEL"),
    }
    return {key: value for key, value in mapping.items() if value is not None}


def load_service_config(
    *,
    config_path: Path | None = None,
    overrides: dict[str, Any] | None = None,
    env: dict[str, str] | None = None,
) -> ServiceConfig:
    """Merge config file, environment, and explicit overrides into a config object."""

    merged: dict[str, Any] = {}
    merged.update(_load_json_config(config_path))
    merged.update(_load_env_config(env))
    if overrides:
        merged.update({key: value for key, value in overrides.items() if value is not None})

    partial = PartialServiceConfig.model_validate(merged)
    return ServiceConfig.model_validate(partial.model_dump(exclude_none=True))

"""HTTP authentication helpers."""

from __future__ import annotations

from starlette.responses import JSONResponse


class StaticBearerAuthMiddleware:
    """Simple ASGI middleware for static Bearer token protection."""

    def __init__(self, app, token: str):
        self.app = app
        self._expected_header = f"Bearer {token}"

    async def __call__(self, scope, receive, send) -> None:
        if scope.get("type") != "http":
            await self.app(scope, receive, send)
            return

        headers = {
            key.decode("latin1").lower(): value.decode("latin1")
            for key, value in scope.get("headers", [])
        }
        if headers.get("authorization") != self._expected_header:
            response = JSONResponse(
                {"error": "Unauthorized"},
                status_code=401,
                headers={"WWW-Authenticate": "Bearer"},
            )
            await response(scope, receive, send)
            return

        await self.app(scope, receive, send)


def wrap_http_auth(app, auth_token: str | None):
    """Wrap an ASGI app with static bearer auth when configured."""

    if not auth_token:
        return app
    return StaticBearerAuthMiddleware(app, auth_token)
